<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { RouterLink, useRoute, useRouter } from 'vue-router';
import { RouteRecordDetailSchema, RouteRecordExportSchema, RouteRecordsResponseSchema, type RouteRecord } from '../../../../packages/contracts/src/observability';
import { runtimeStateLabels, type RuntimeConfig } from '../../../../packages/contracts/src/index';
import { runtimeRequest } from '../../api/typescript';
import AuditPreview from './AuditPreview.vue';
import RecordFilters from './RecordFilters.vue';
import { recordFiltersFromQuery, recordOffset, recordSearchParams, routeOutcomeLabels, recordPlatform, formatRecordTime, formatRecordDuration, routeNodeLabels, routeStepSummary, routeSummaryText, routeAgentRunIds, routeProcessingState } from './observability-model';

const props=defineProps<{config:RuntimeConfig;disabled?:boolean}>();
const route=useRoute();const router=useRouter();const filters=ref(recordFiltersFromQuery(route.query));
const records=ref<RouteRecord[]>([]);const total=ref(0);const limit=ref(50);const listLoading=ref(false);const detailLoading=ref(false);const error=ref('');const notice=ref('');
const detail=ref<ReturnType<typeof RouteRecordDetailSchema.parse>>();let listVersion=0;let detailVersion=0;let disposed=false;let listController:AbortController|undefined;let detailController:AbortController|undefined;
const offset=computed(()=>recordOffset(route.query.offset));const selectedId=computed(()=>typeof route.query.record==='string'?route.query.record:typeof route.query.routeRecordId==='string'?route.query.routeRecordId:'');
const busy=computed(()=>listLoading.value||detailLoading.value||props.disabled);
const platformOptions=computed(()=>{const data=new Map(props.config.platforms.map(item=>[item.id,`${item.type==='napcat'?'QQ / NapCat':item.type==='telegram'?'Telegram':'微信'} · ${item.displayName||item.id}`]));for(const record of records.value)if(!data.has(record.platform))data.set(record.platform,`${recordPlatform(record.platform,record.platformType)} · ${record.platform}`);return [...data].map(([id,label])=>({id,label}));});
const agentOptions=computed(()=>props.config.agents.map(item=>({id:item.id,label:item.displayName})));
const relatedRuns=computed(()=>detail.value?routeAgentRunIds(detail.value):[]);
const processingState=computed(()=>detail.value?routeProcessingState(detail.value):null);
function agentName(id:string|null):string{return props.config.agents.find(item=>item.id===id)?.displayName || id || '未选择 Agent';}
async function loadList():Promise<void>{const version=++listVersion;listController?.abort();listController=new AbortController();listLoading.value=true;error.value='';try{const data=await runtimeRequest(`route-records?${recordSearchParams(recordFiltersFromQuery(route.query),'route',offset.value)}`,RouteRecordsResponseSchema,undefined,'GET',listController.signal);if(disposed||version!==listVersion)return;records.value=data.records;total.value=data.total;limit.value=data.limit;}catch(cause){if(version===listVersion&&!(cause instanceof Error&&cause.name==='AbortError'))error.value=cause instanceof Error?cause.message:'路由记录读取失败。请重试。';}finally{if(version===listVersion)listLoading.value=false;}}
async function loadDetail():Promise<void>{const version=++detailVersion;detailController?.abort();detail.value=undefined;notice.value='';error.value='';if(!selectedId.value){detailLoading.value=false;return;}const id=selectedId.value;detailController=new AbortController();detailLoading.value=true;try{const data=await runtimeRequest(`route-records/${encodeURIComponent(id)}`,RouteRecordDetailSchema,undefined,'GET',detailController.signal);if(!disposed&&version===detailVersion)detail.value=data;}catch(cause){if(version===detailVersion&&!(cause instanceof Error&&cause.name==='AbortError'))error.value=cause instanceof Error?cause.message:'路由详情读取失败。请重试。';}finally{if(version===detailVersion)detailLoading.value=false;}}
async function apply(reset=false):Promise<void>{if(reset)filters.value=recordFiltersFromQuery({});try{recordSearchParams(filters.value,'route');const value=filters.value;const previous=route.fullPath;await router.replace({query:{platform:value.platform||undefined,sessionType:value.sessionType||undefined,sessionId:value.sessionId||undefined,agentId:value.agentId||undefined,search:value.search.trim()||undefined,from:value.from||undefined,to:value.to||undefined,outcome:value.outcome||undefined}});if(previous===route.fullPath)await loadList();}catch(cause){error.value=cause instanceof Error?cause.message:'请检查筛选条件。';}}
async function select(id:string):Promise<void>{if(selectedId.value===id){await loadDetail();return;}await router.push({query:{...route.query,record:id,routeRecordId:undefined}});}
async function page(delta:number):Promise<void>{await router.push({query:{...route.query,offset:String(Math.max(0,offset.value+delta*limit.value)),record:undefined,routeRecordId:undefined}});}
async function refresh():Promise<void>{await Promise.all([loadList(),loadDetail()]);}
async function exportRecord():Promise<void>{const id=selectedId.value;if(!id)return;try{const data=await runtimeRequest(`route-records/${encodeURIComponent(id)}/export`,RouteRecordExportSchema);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`priestessbot-route-${id.slice(0,12)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='路由审计记录已导出。导出内容仍遵守脱敏和长度限制。';}catch(cause){error.value=cause instanceof Error?cause.message:'导出失败。请重试。';}}
onMounted(()=>{void refresh();});
watch([()=>route.query.platform,()=>route.query.sessionType,()=>route.query.sessionId,()=>route.query.agentId,()=>route.query.search,()=>route.query.from,()=>route.query.to,()=>route.query.outcome,()=>route.query.offset],()=>{filters.value=recordFiltersFromQuery(route.query);void loadList();});
watch(selectedId,()=>{void loadDetail();});
onBeforeUnmount(()=>{disposed=true;listVersion++;detailVersion++;listController?.abort();detailController?.abort();});
</script>
<template><section class="record-workspace route-records-workspace" aria-label="路由记录工作区"><header class="section-title"><div><h2>路由记录</h2><p>查看消息是否进入处理，以及在哪一步被忽略、拒绝或分配给 Agent。</p></div><button type="button" :disabled="busy" @click="refresh">刷新记录</button></header><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="notice" class="notice ok" role="status">{{notice}}</p><RecordFilters v-model="filters" kind="route" :busy="!!busy" :platforms="platformOptions" :agents="agentOptions" @apply="apply()" @reset="apply(true)"/>
  <div class="record-columns"><aside class="record-list" aria-label="路由记录列表"><div class="record-list-count"><strong>{{total}} 条匹配记录</strong><small v-if="total">{{offset+1}}–{{Math.min(offset+records.length,total)}}</small></div><p v-if="listLoading" class="empty-state" role="status">正在读取路由记录…</p><button v-for="item in records" :key="item.id" type="button" :class="{selected:selectedId===item.id}" @click="select(item.id)"><strong>{{routeOutcomeLabels[item.outcome]}}</strong><small>{{recordPlatform(item.platform,item.platformType)}} · {{item.sessionType==='group'?'群聊':'私聊'}} · {{item.sessionName||item.sessionId}}</small><span>{{item.inputPreview?.text || routeSummaryText(item.reason) || '没有输入预览'}}</span><small>{{formatRecordTime(item.createdAt)}}</small></button><p v-if="!listLoading&&!records.length" class="empty-state">没有匹配的路由记录。清空筛选后重试；新消息接入后会记录处理结果。</p><div class="record-pagination"><button type="button" :disabled="busy||offset===0" @click="page(-1)">上一页</button><button type="button" :disabled="busy||offset+records.length>=total" @click="page(1)">下一页</button></div></aside>
    <section v-if="detail" class="record-detail" aria-label="路由详情"><header class="record-detail-heading"><div><p class="record-eyebrow">{{formatRecordTime(detail.record.createdAt)}}</p><h3>{{routeOutcomeLabels[detail.record.outcome]}}</h3><small>{{detail.record.id}}</small></div><button type="button" @click="exportRecord">导出记录</button></header><p v-if="detail.record.legacy" class="notice">这是旧执行记录的恢复信息。缺少的原始输入和路由步骤不会补造。</p><dl class="record-facts"><div><dt>来源</dt><dd>{{recordPlatform(detail.record.platform,detail.record.platformType)}} · {{detail.record.platform}}</dd></div><div><dt>会话</dt><dd>{{detail.record.sessionType==='group'?'群聊':'私聊'}} · {{detail.record.sessionName||detail.record.sessionId}}</dd></div><div><dt>发送者</dt><dd>{{detail.record.senderName||detail.record.senderId}} <small>{{detail.record.senderName?detail.record.senderId:''}}</small></dd></div><div><dt>耗时</dt><dd>{{formatRecordDuration(detail.record.durationMs)}}</dd></div><div><dt>目标 Agent</dt><dd>{{agentName(detail.record.agentId)}}</dd></div><div><dt>运行态</dt><dd>{{detail.record.runtimeState?runtimeStateLabels[detail.record.runtimeState]:'未记录'}}</dd></div></dl><p v-if="detail.record.reason" class="record-reason">{{routeSummaryText(detail.record.reason)}}</p><AuditPreview title="接入消息预览" :preview="detail.record.inputPreview"/>
      <section v-if="processingState" aria-label="消息处理状态"><h4>消息处理状态</h4><dl class="record-facts"><div><dt>当前状态</dt><dd>{{processingState.label}}</dd></div></dl><p v-if="processingState.summary" class="record-reason">{{processingState.summary}}</p><p class="muted">{{processingState.note}}</p></section><section><h4>路由步骤</h4><p class="muted">各步骤未单独计时。顶部耗时为整体路由处理时间。</p><ol v-if="detail.record.path.length" class="route-step-list"><li v-for="(step,index) in detail.record.path" :key="`${index}:${step.nodeId}`" :class="step.status"><strong>{{routeNodeLabels[step.nodeId]}}</strong><span>{{step.status==='passed'?'通过':step.status==='ignored'?'忽略':'拒绝'}}</span><p>{{routeStepSummary(step)}}</p></li></ol><p v-else class="muted">此记录没有保存路由步骤。</p></section>
      <nav class="record-links" aria-label="路由关联对象"><RouterLink v-for="id in relatedRuns" :key="id" class="button-link" :to="{path:'/agent-records',query:{run:id}}">查看 Agent 记录 {{id.slice(0,8)}}</RouterLink><RouterLink class="button-link" :to="{path:'/sessions',query:{platform:detail.record.platform,sessionType:detail.record.sessionType,sessionId:detail.record.sessionId}}">查看平台会话</RouterLink><RouterLink v-if="detail.record.agentId" class="button-link" :to="{path:'/agents',query:{agent:detail.record.agentId}}">查看目标 Agent</RouterLink><RouterLink class="button-link" to="/flow">查看路由配置</RouterLink></nav><p v-if="!relatedRuns.length&&!processingState" class="muted">此消息没有关联 Agent 运行。</p><details v-if="detail.record.path.length"><summary>原始路由字段</summary><ol class="record-events"><li v-for="(step,index) in detail.record.path" :key="`${index}:${step.nodeId}`"><code>{{step.nodeId}}</code> · {{step.status}}<p>{{step.summary}}</p></li></ol><p class="muted">原始字段用于排查。各步骤没有单独计时。</p></details><details><summary>记录版本与消息标识</summary><dl class="record-facts"><div><dt>配置修订</dt><dd>{{detail.record.configRevision ?? '未记录'}}</dd></div><div><dt>路由修订</dt><dd>{{detail.record.flowRevision ?? '未记录'}}</dd></div><div><dt>消息 ID</dt><dd>{{detail.record.messageId || '未记录'}}</dd></div><div><dt>会话 ID</dt><dd>{{detail.record.sessionId}}</dd></div></dl></details>
    </section><section v-else class="record-detail empty-state" role="status">{{detailLoading?'正在读取路由详情…':'选择一条路由记录查看处理步骤。'}}</section>
  </div>
</section></template>
<style scoped src="./records.css"></style>
